        assertEquals(-35.0, Math.toDegrees(result.thetaRad), 1.0) // 1-degree search granularity
        assertTrue("Correlation should be near-perfect on this clean synthetic signal", result.correlation > 0.999)
    }

    @Test
    fun calibrate_fallsBack_whenInsufficientMovingSamples() {
        // Only 50 samples, all below the 100-sample moving-mask threshold.
        val n = 50
        val t = DoubleArray(n) { it * 0.5 }
        val vGps = DoubleArray(n) { 10.0 } // constant, moving, but not enough samples
        val axLin = DoubleArray(n) { 0.1 }
        val ayLin = DoubleArray(n) { 0.1 }

        val result = MountingYawCalibrator.calibrate(t, vGps, axLin, ayLin)
        assertFalse(result.calibrated)
        assertEquals(0.0, result.thetaRad, 1e-9)
    }
}
